def compute(vars):
    net_income = vars["Net Income"]
    average_equity = vars["Average Equity"]

    if average_equity == 0:
        return None

    roe = net_income / average_equity

    return {
        "value": roe,
        "trace": {
            "Net Income": net_income,
            "Average Equity": average_equity,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
